-- +goose StatementBegin
INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.69.0',
  '2026-08-05',
  'Finance: фактические траты, дерево категорий, счета и цели, отчёт по группам и месяцам',
  E'Finance, фазы 3–4. Вкладка «Траты»: расходы, доходы и переводы между счетами — дата, категория, счёт, магазин, фильтры по месяцу/категории/счёту и поиск.\n\nКатегории стали деревом любой вложенности («Еда → Продукты → Овощи»), типовой набор создаётся одной кнопкой. Удаление категории деньги не теряет: подкатегории и записи поднимаются на уровень выше.\n\nВкладка «Счета» — откуда деньги: остаток считается от стартового по записям, переводы расходом не считаются. Там же цели «Отложено на»: конверт поверх счёта, видно, сколько из остатка уже занято.\n\nВкладка «Отчёт»: расходы по месяцам столбиками (3/6/12 месяцев, нажатие на месяц показывает только его) и по группам — доля каждой категории, сравнение с прошлым периодом такой же длины, проваливание внутрь группы.\n\nОплата планового платежа теперь сама попадает в «Траты» с категорией и счётом плана, поэтому отчёт считается по всем деньгам сразу. В сводке добавились «Потрачено (факт)» и «На счетах».',
  E'Реестр денег ОДИН — finance_transactions. PayFinancePlan в той же транзакции пишет finance_payments и обычную транзакцию (plan_id + payment_id); пропуск транзакции не создаёт. finance_payments остаётся журналом «за какую дату платежа заплатили» (среднее для примерных сумм, periods).\n\nМиграция 0085: finance_categories (parent_id на себя, unique (user_id, coalesce(parent_id,0), lower(name))), finance_accounts, finance_transactions (kind expense|income|transfer, rate_to_base, external_id с частичным unique-индексом под будущий импорт писем), finance_goals + finance_goal_moves, finance_plans.category_id/account_id. Текстовые категории планов перенесены в дерево по названиям; plans.category остаётся денормализованным именем и обновляется вместе с category_id.\n\nУдаление категории поднимает детей, транзакции и планы на родителя — каскад стёр бы траты, а SET NULL обезличил бы их. Перенос категории в собственного потомка отбивается рекурсивным CTE. Фильтр по категории раскрывает поддерево рекурсивным CTE. Счёт с движениями не удаляется (409) — только архив.\n\nОстаток счёта = стартовый плюс движения, чужая валюта приводится ЖИВЫМ курсом (остаток — величина «на сейчас»); в отчёте наоборот берётся курс, зафиксированный в записи, и только если базовая валюта не менялась — иначе прошлые месяцы «плыли» бы.\n\nGET /finance/stats считает в Go по сырым строкам периода: свёртка дерева и сравнение с прошлым периодом той же длины в SQL нечитаемы, а объёмы личных финансов ничтожны. Средний месяц — по месяцам с записями. GET /finance/refs отдаёт категории, счета с остатками, цели и валюты одним запросом.\n\nПроверено: seed дважды не плодит дублей, дубль имени → 409 (важно: pgx отдаёт нарушение уникальности из CollectOneRow, а не из Query), цикл в дереве → 409, фильтр по группе включает подкатегории, балансы (100000+400000−5000−3000−10000=482000), оплата плана создаёт транзакцию с его категорией и счётом, удаление категории сохраняет все 4 траты, счёт с движениями → 409; в браузере — все пять вкладок, добавление траты, отчёт. Фикс на месте: столбики расходов масштабировались по доходу и схлопывались в полоску.'
);
